import { weekStart } from '../src/lib/duration.ts';

describe('การนับสัปดาห์สำหรับโควตา (REQ-15)', () => {
  test('สัปดาห์เริ่มวันจันทร์ 00:00 — วันจันทร์เอง อยู่ในสัปดาห์ของตัวเอง', () => {
    assert.equal(weekStart('2026-08-03T00:00:00.000Z'), '2026-08-03T00:00:00.000Z');
  });

  test('วันอาทิตย์ท้ายสัปดาห์ ยังอยู่ในสัปดาห์ก่อนหน้า', () => {
    assert.equal(weekStart('2026-08-09T23:59:59.999Z'), '2026-08-03T00:00:00.000Z');
  });

  test('วันจันทร์ถัดไป เริ่มสัปดาห์ใหม่ทันที 00:00', () => {
    assert.equal(weekStart('2026-08-10T00:00:00.000Z'), '2026-08-10T00:00:00.000Z');
  });

  test('การจองวันอาทิตย์กับวันจันทร์ถัดไป นับคนละสัปดาห์', () => {
    const sunday = weekStart('2026-08-09T23:59:59.999Z');
    const monday = weekStart('2026-08-10T00:00:00.000Z');
    assert.notEqual(sunday, monday);
  });

  test('กลางสัปดาห์ (พุธ) ย้อนกลับไปหาจันทร์ของสัปดาห์เดียวกัน', () => {
    assert.equal(weekStart('2026-08-05T15:30:00.000Z'), '2026-08-03T00:00:00.000Z');
  });
});

